package com.boutique.order.controller;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> notFound(Exception e){return response(HttpStatus.NOT_FOUND,e);}@ExceptionHandler({IllegalStateException.class,IllegalArgumentException.class}) ResponseEntity<?> conflict(Exception e){return response(HttpStatus.CONFLICT,e);}private ResponseEntity<?> response(HttpStatus s,Exception e){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s.value(),"error",s.getReasonPhrase(),"message",e.getMessage()));}}
